SELECT percentile_cont(0.25) within GROUP (ORDER BY icustays.los) AS percentile_25 FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'M' AND patients.anchor_age = 78 AND EXTRACT(YEAR FROM admissions.admittime) BETWEEN 2013 AND 2014 AND (admissions.admission_type = 'DKA' OR admissions.admission_type = 'HHS') AND (icustays.intime - admissions.admittime) / (60 * 60 * 24) <= 7;